import { Component } from '@angular/core';
import { Pienso } from 'src/app/models/pienso';
import { PiensoService } from 'src/app/services/pienso.service';

@Component({
  selector: 'app-categorias',
  templateUrl: './categorias.component.html',
  styleUrls: ['./categorias.component.css']
})
export class CategoriasComponent {


  //CATEGORIAS FILTROS PIENSOS
  constructor(private piensoService: PiensoService){}


  //BOTON VER TODOS LOS PRODUCTOS
  mostrarTodosLosProductos() {
    this.piensoService.getPiensos().subscribe(
      piensos => {
        this.piensoService.piensos = piensos;
      },
      error => {
        console.error('Error al obtener todos los productos', error);
      }
    );
  }


  //Es un metodo que le pasas el tipo de animal como parametro y te busca lo que le pidas
  filtrarPorTipo(tipoAnimal: string) {
    this.piensoService.getPiensosPorTipo(tipoAnimal).subscribe( //te busca los piensos del animal que introduzcas por paramtero
      piensos => {
        this.piensoService.piensos = piensos; //muestra los piensos
      }
    );
  }


  //POR PRECIO
  filtrarPorPrecio(rangoPrecio: string) {
    this.piensoService.getPiensosPorPrecio(rangoPrecio).subscribe(
      piensos => {
        this.piensoService.piensos = piensos;
      }
    );
  }


  //POR PESOS
  filtrarPorPeso(rangoPeso: string) {
    this.piensoService.getPiensosPorPeso(rangoPeso).subscribe(
      piensos => {
        this.piensoService.piensos = piensos;
      }
    );
  }


  //FILTRAR POR EDAD DEL ANIMAL (JUNIOR, ADULTO Y SENIOR)
  filtrarPorEdad(rangoEdad: string) {
  this.piensoService.getPiensosPorEdad(rangoEdad).subscribe(
    piensos => {
      this.piensoService.piensos = piensos;
    }
  );
  }



  filtros = {
    precio: '',
    peso: '',
    edad: ''
  };

  // Método para actualizar los filtros y realizar la petición
  aplicarFiltros() {
    this.piensoService.getPiensosConFiltros(this.filtros).subscribe(
      piensos => {
        this.piensoService.piensos = piensos;
      },
      error => {
        console.error('Error al obtener piensos filtrados', error);
      }
    );
  }


}
<!--TODOS LOS PRODUCTOS-->
<br>
<li class="list-group-item" style="color: #f79191; font-weight: bold; font-size: 1.2em; margin-left: 13px;">Todos</li>

<li class="list-group-item">
  <a (click)="mostrarTodosLosProductos()" style="text-decoration: none; cursor: pointer; color: blue; margin-left: 15px;">Ver todos los productos</a>
</li>


<br>
<ul class="list-group list-group-flush" style="margin-bottom: 7%;">
  <li class="list-group-item" style="color: #f79191; font-weight: bold; font-size: 1.2em; ">Perros</li>

  <!--FILTROS PIENSOS PERROS-->
    <li class="list-group-item">
      <a (click)="filtrarPorTipo('Perro')" style="text-decoration: none; cursor: pointer; color: blue;">Comida para perros</a>
    </li>

</ul>

<ul class="list-group list-group-flush">
    <li class="list-group-item" style="color: #f79191; font-weight: bold; font-size: 1.2em;">Gatos</li>

    <!--FILTROS PIENSOS GATOS-->
    <li class="list-group-item">
      <a (click)="filtrarPorTipo('Gato')" style="text-decoration: none; cursor: pointer; color: blue;">Comida para gatos</a>
    </li>

</ul>

<br>

   <!--FILTROS POR PRECIO-->
<li class="list-group-item" style="color: #f79191; font-weight: bold; font-size: 1.2em;">Precios</li>
<!-- Crear un grupo de checkboxes para el precio -->
<div class="form-check" *ngFor="let precio of rangosPrecio">
  <input type="checkbox" class="form-check-input" id="{{'precio' + precio}}" (change)="aplicarFiltroPrecio(precio)" [checked]="filtros.precio.includes(precio)">
  <label class="form-check-label" for="{{'precio' + precio}}">{{ precio }}</label>
</div>

<br>
<!--FILTROS POR PESO-->
<li class="list-group-item" style="color: #f79191; font-weight: bold; font-size: 1.2em;">Peso</li>
<!-- Crear un grupo de checkboxes para el peso -->
<div class="form-check" *ngFor="let peso of rangosPeso">
  <input type="checkbox" class="form-check-input" id="{{'peso' + peso}}" (change)="aplicarFiltroPeso(peso)" [checked]="filtros.peso.includes(peso)">
  <label class="form-check-label" for="{{'peso' + peso}}">{{ peso }}</label>
</div>

<br>
<!--FILTROS POR EDAD-->
<li class="list-group-item" style="color: #f79191; font-weight: bold; font-size: 1.2em;">Buscar por tipo de edad</li>
<div class="form-check" *ngFor="let edad of ['Junior', 'Adulto', 'Senior']">
  <input type="checkbox" class="form-check-input" id="{{'edad' + edad}}" (change)="aplicarFiltroEdad(edad)" [checked]="filtros.edad.includes(edad)">
  <label class="form-check-label" for="{{'edad' + edad}}">{{ edad }}</label>
</div>
